fn solve(s: Vec<char>) -> &'static str {
    let mut stack: Vec<char> = Vec::new();
    let mut removal_count = 0;

    for &c in s.iter() {
        if let Some(&top) = stack.last() {
            if top == c {
                stack.pop(); // Remove the last character as it matches the current one
                removal_count += 1; // Increment the removal count
            } else {
                stack.push(c); // Push the current character onto the stack
            }
        } else {
            stack.push(c); // Stack is empty, just push the current character
        }
    }

    // Check if the removal count is odd or even
    if removal_count % 2 == 1 {
        "Yes"
    } else {
        "No"
    }
}